// ERCOT 공개 API 는 deliveryDate 로 조회한다. D+1~D+4 범위를 만든다.
// n8n 서버는 UTC 라 '오늘'은 반드시 America/Chicago 기준으로 잡아야 한다.
const ctToday = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Chicago' });
const day = n => {
  const d = new Date(ctToday + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
return [{ json: { dateFrom: day(1), dateTo: day(4), ctToday } }];

// ERCOT 공개 API 3종 + Open-Meteo -> /predict 페이로드.
//
// ERCOT 응답은 { fields:[{name:...}], data:[[...]] } 형태다(객체 배열이 아니다).
// 컬럼 이름은 리포트 개정 때 바뀔 수 있으므로 순서가 아니라 '이름 부분매칭'으로 찾는다
// — 파이썬 모델의 NEEDLES 와 같은 이유다. 못 찾으면 실제 컬럼 목록을 담아 예외를 던진다.
// 조용한 NaN 보다 시끄러운 실패가 낫다.

function table(resp, label) {
  const fields = (resp && resp.fields) || [];
  const rows = (resp && resp.data) || [];
  if (!fields.length || !rows.length) {
    throw new Error(`${label}: ERCOT 응답이 비었습니다. 구독키/토큰 또는 조회 날짜를 확인하세요.`);
  }
  return { cols: fields.map(f => f.name), rows };
}

function idx(cols, label, what, alts) {
  for (const a of alts) {
    const i = cols.findIndex(c => String(c).toLowerCase().includes(a.toLowerCase()));
    if (i >= 0) return i;
  }
  throw new Error(`${label}: ${what} 컬럼을 못 찾았습니다. 찾아본 이름: ${alts.join(', ')} / ` +
                  `실제 컬럼: ${cols.join(', ')}`);
}

// hourEnding 은 소스에 따라 "1".."24" 또는 "0100".."2400" 로 온다. 시작시각(0~23)으로 정규화.
function startHour(v) {
  const n = parseInt(String(v).replace(':', ''), 10);
  const he = n > 24 ? Math.floor(n / 100) : n;
  return he - 1;
}
const stamp = (d, h) => `${String(d).slice(0, 10)}T${String(h).padStart(2, '0')}:00:00`;

// ---------- 부하 예보 ----------
const L = table($('ERCOT Load Forecast').first().json, '부하 예보');
const Ld = idx(L.cols, '부하 예보', '날짜', ['deliveryDate', 'date']);
const Lh = idx(L.cols, '부하 예보', '시간', ['hourEnding', 'hour']);
const Lv = idx(L.cols, '부하 예보', '시스템 전체 부하', ['systemTotal', 'systemWide', 'system_wide', 'system']);
const Lu = L.cols.findIndex(c => /inuse/i.test(String(c)));   // 여러 모델 중 실제 사용본 표시

const load = {};
for (const r of L.rows) {
  if (Lu >= 0) {
    const f = String(r[Lu]).toLowerCase();
    if (f === 'false' || f === 'n' || f === '0' || f === '') continue;
  }
  const t = stamp(r[Ld], startHour(r[Lh]));
  const v = Number(r[Lv]);
  if (!Number.isNaN(v)) load[t] = v;          // 같은 키가 또 오면 최신값으로 덮는다
}

// ---------- 풍력 / 태양광 예보 ----------
// STWPF = Short-Term Wind Power Forecast, STPPF = Short-Term PV Power Forecast.
function genMap(nodeName, label, valueAlts) {
  const T = table($(nodeName).first().json, label);
  const d = idx(T.cols, label, '날짜', ['deliveryDate', 'date']);
  const h = idx(T.cols, label, '시간', ['hourEnding', 'hour']);
  const v = idx(T.cols, label, '시스템 전체 발전', valueAlts);
  const m = {};
  for (const r of T.rows) {
    const x = Number(r[v]);
    if (!Number.isNaN(x)) m[stamp(r[d], startHour(r[h]))] = x;
  }
  return m;
}
const wind = genMap('ERCOT Wind Forecast', '풍력 예보',
                    ['STWPF_SYSTEM_WIDE', 'stwpfSystemWide', 'systemWide', 'system_wide', 'systemTotal']);
const solar = genMap('ERCOT Solar Forecast', '태양광 예보',
                     ['STPPF_SYSTEM_WIDE', 'stppfSystemWide', 'systemWide', 'system_wide', 'systemTotal']);

// ---------- 시간별 예보 합치기 ----------
const forecast = Object.keys(load).sort().map(t => ({
  timestamp: t,
  fc_load_mw: load[t],
  fc_wind_mw: wind[t] ?? 0,
  fc_solar_mw: solar[t] ?? 0,
}));

const days = [...new Set(forecast.map(r => r.timestamp.slice(0, 10)))].sort();
if (forecast.length < 24) {
  throw new Error(`D+1~D+4 예보가 부족합니다 (${forecast.length}행, 24행 이상 필요). ` +
                  `받은 날짜: ${days.join(', ') || '없음'}. 조회 범위나 인증을 확인하세요.`);
}
const noWind = forecast.filter(r => !(r.timestamp in wind)).length;
if (noWind > forecast.length / 2) {
  throw new Error(`풍력 예보가 ${noWind}/${forecast.length} 시간에서 비었습니다. ` +
                  `시간 키가 안 맞는 것으로 보입니다(hourEnding 형식 확인).`);
}

// ---------- Open-Meteo 4개 도시 기온 -> 날짜별 4-city 평균 ----------
// 학습 데이터가 'Texas 4-city average' 라 같은 방식으로 접는다:
// 도시별 일평균/일최고를 낸 뒤 도시 간 평균. (전체를 뭉뚱그려 max 잡으면 기준이 달라진다.)
const wxRaw = $('Open-Meteo 4-city').all().map(i => i.json);
const locs = wxRaw.flatMap(x => Array.isArray(x) ? x : [x]).filter(x => x && x.hourly);
const perDate = {};
for (const loc of locs) {
  const t = loc.hourly.time || [], v = loc.hourly.temperature_2m || [];
  const day = {};
  for (let i = 0; i < t.length; i++) {
    const d = String(t[i]).slice(0, 10), x = Number(v[i]);
    if (!d || Number.isNaN(x)) continue;
    if (!day[d]) day[d] = { sum: 0, n: 0, max: -Infinity };
    day[d].sum += x; day[d].n++; if (x > day[d].max) day[d].max = x;
  }
  for (const [d, a] of Object.entries(day)) {
    if (a.n < 24) continue;
    if (!perDate[d]) perDate[d] = { means: [], maxes: [] };
    perDate[d].means.push(a.sum / a.n);
    perDate[d].maxes.push(a.max);
  }
}
const avg = a => a.reduce((s, x) => s + x, 0) / a.length;
const weather = Object.entries(perDate)
  .filter(([d]) => days.includes(d))
  .map(([date, a]) => ({ date,
                         temp_mean_f: Number(avg(a.means).toFixed(2)),
                         temp_max_f: Number(avg(a.maxes).toFixed(2)) }))
  .sort((a, b) => a.date < b.date ? -1 : 1);

if (weather.length < days.length) {
  throw new Error(`예보 ${days.length}일 중 기온이 있는 날은 ${weather.length}일뿐입니다. ` +
                  `날씨 없이 돌리면 M1 날씨피처와 오버레이가 죽습니다.`);
}

return [{ json: {
  forecast,
  weather,
  volume_mw: 100,
  use_gate: false,
  run_id: new Date().toISOString().slice(0, 19).replace(/[-:]/g, '')
}}];

// Claude 에 넘길 컨텍스트 구성. 원본 수치를 그대로 주고 해석만 요청한다.
const rows = $('Flatten Rows').all().map(i => i.json);
const compact = rows.map(r => ({
  horizon: r.horizon, date: r.target_date, DA_pct: r.DA_fraction,
  alloc_mode: r.alloc_mode, m1_threshold: r.m1_threshold,
  M1: r.M1_P_DA_cheaper, M2_DA_USD: r.M2_DA_pred_USD, M4_basis: r.M4_premium_prob,
  wx_anom_F: r.WX_t_anom_F, overlay: r.WX_overlay, gate: r.M3_gate_reason
}));
return [{ json: { run_id: rows[0].run_id, payload: JSON.stringify(compact) } }];

